"use client";

import { useTemplateCopy } from "@/components/ui/template-copy/template-copy";

import { RiNotificationLine } from "@remixicon/react";
import { useRef, useState } from "react";
import { Dialog, Popover } from "react-aria-components";

import { STARTER_NOTIFICATIONS } from "@/components/ui/app-shell/starter-notifications";
import {
  NotificationCenter,
  type NotificationCenterItem,
} from "@/components/ui/notification-center/notification-center";
import { IconButton } from "@/components/ui/buttons/icon-button";
import { useDismissOnOutsidePress } from "@/lib/use-dismiss-on-outside-press";

/** The header's bell: unread count on the glyph, the notification center in a popover. */
export function NotificationBell({
  notifications = STARTER_NOTIFICATIONS,
}: {
  notifications?: NotificationCenterItem[];
} = {}) {
  const localize = useTemplateCopy();
  const triggerRef = useRef<HTMLButtonElement>(null);
  const popoverRef = useRef<HTMLElement>(null);
  const [isOpen, setIsOpen] = useState(false);
  const unread = notifications.filter((item) => item.unread).length;

  useDismissOnOutsidePress(isOpen, () => setIsOpen(false), [triggerRef, popoverRef]);

  return localize((
    <>
      <span className="group relative inline-flex">
        <IconButton
          ref={triggerRef}
          icon={RiNotificationLine}
          size="medium"
          aria-label="Notifications"
          aria-expanded={isOpen}
          aria-haspopup="dialog"
          onClick={() => setIsOpen((open) => !open)}
        />
        {unread > 0 && (
          <span className="pointer-events-none absolute top-0.5 start-[18px] flex size-4 items-center justify-center rounded-full border-[1.5px] border-background-primary-default bg-badge-count group-hover:border-0 group-active:border-0">
            <span className="w-4 text-center text-[10px] leading-4 font-bold text-text-white">{unread}</span>
          </span>
        )}
      </span>
      <Popover
        ref={popoverRef}
        triggerRef={triggerRef}
        isOpen={isOpen}
        onOpenChange={setIsOpen}
        placement="bottom end"
        offset={8}
        isNonModal
        className="z-50 w-[440px] max-w-[calc(100vw-24px)] outline-none"
      >
        <Dialog aria-label="Notifications" className="outline-none">
          <NotificationCenter notifications={notifications} />
        </Dialog>
      </Popover>
    </>
  ));
}
